import hashlib
import hmac
import time
import os
import secrets
from dataclasses import dataclass, field
from typing import Optional, Dict, List
from enum import Enum
import json

from cryptography.hazmat.primitives.ciphers.aead import AESGCM


class Role(Enum):
    ADMIN = "admin"
    DEVELOPER = "developer"
    VIEWER = "viewer"


@dataclass
class User:
    user_id: str
    username: str
    role: Role
    org_id: str
    team_ids: List[str] = field(default_factory=list)


@dataclass
class Pipeline:
    pipeline_id: str
    name: str
    owner_id: str
    org_id: str
    team_id: str
    secrets: Dict[str, str] = field(default_factory=dict)
    is_private: bool = False


class AccessControlMatrix:
    """Defines permission boundaries for pipeline operations."""

    PERMISSIONS = {
        Role.ADMIN: ["read", "write", "delete", "execute", "manage_secrets"],
        Role.DEVELOPER: ["read", "write", "execute"],
        Role.VIEWER: ["read"],
    }

    @staticmethod
    def role_has_permission(role: Role, permission: str) -> bool:
        return permission in AccessControlMatrix.PERMISSIONS.get(role, [])


class PipelineAccessChecker:
    """Multi-layer access control for CI/CD pipeline operations."""

    def __init__(self, audit_log=None):
        self.audit_log = audit_log or []

    def check_org_membership(self, user: User, pipeline: Pipeline) -> bool:
        """Layer 1: Verify user belongs to same organization."""
        return user.org_id == pipeline.org_id

    def check_team_membership(self, user: User, pipeline: Pipeline) -> bool:
        """Layer 2: Verify user belongs to the pipeline's team."""
        if user.role == Role.ADMIN:
            return True
        return pipeline.team_id in user.team_ids

    def check_ownership_or_role(self, user: User, pipeline: Pipeline, operation: str) -> bool:
        """Layer 3: Check if user owns pipeline or has sufficient role."""
        if user.user_id == pipeline.owner_id:
            return True
        return AccessControlMatrix.role_has_permission(user.role, operation)

    def check_private_access(self, user: User, pipeline: Pipeline) -> bool:
        """Layer 4: Additional check for private pipelines."""
        if not pipeline.is_private:
            return True
        return user.user_id == pipeline.owner_id or user.role == Role.ADMIN

    def authorize(self, user: User, pipeline: Pipeline, operation: str) -> bool:
        """Main authorization entry point - all layers must pass."""
        if not self.check_org_membership(user, pipeline):
            self._log_denial(user, pipeline, operation, "org_mismatch")
            return False

        if not self.check_team_membership(user, pipeline):
            self._log_denial(user, pipeline, operation, "team_mismatch")
            return False

        if not self.check_ownership_or_role(user, pipeline, operation):
            self._log_denial(user, pipeline, operation, "insufficient_role")
            return False

        if not self.check_private_access(user, pipeline):
            self._log_denial(user, pipeline, operation, "private_access_denied")
            return False

        self._log_access(user, pipeline, operation)
        return True

    def _log_denial(self, user, pipeline, operation, reason):
        self.audit_log.append({
            "event": "access_denied",
            "user_id": user.user_id,
            "pipeline_id": pipeline.pipeline_id,
            "operation": operation,
            "reason": reason,
            "timestamp": time.time()
        })

    def _log_access(self, user, pipeline, operation):
        self.audit_log.append({
            "event": "access_granted",
            "user_id": user.user_id,
            "pipeline_id": pipeline.pipeline_id,
            "operation": operation,
            "timestamp": time.time()
        })


class PipelineService:
    """Service layer for pipeline CRUD operations."""

    def __init__(self, secret_encryption_key: Optional[bytes] = None):
        self.pipelines: Dict[str, Pipeline] = {}
        self.access_checker = PipelineAccessChecker()
        # 256-bit key for AES-GCM authenticated encryption of pipeline secrets.
        # In production this should be loaded from a secure KMS / secret store.
        if secret_encryption_key is None:
            secret_encryption_key = os.environ.get("PIPELINE_SECRET_KEY", "").encode() or None
        if secret_encryption_key is None:
            secret_encryption_key = AESGCM.generate_key(bit_length=256)
        if len(secret_encryption_key) not in (16, 24, 32):
            raise ValueError("secret_encryption_key must be 128, 192, or 256 bits")
        self._secret_key = secret_encryption_key

    def create_pipeline(self, user: User, name: str, team_id: str,
                        is_private: bool = False) -> Pipeline:
        pipeline_id = secrets.token_hex(16)
        pipeline = Pipeline(
            pipeline_id=pipeline_id,
            name=name,
            owner_id=user.user_id,
            org_id=user.org_id,
            team_id=team_id,
            is_private=is_private
        )
        self.pipelines[pipeline_id] = pipeline
        return pipeline

    def get_pipeline(self, user: User, pipeline_id: str) -> Optional[Pipeline]:
        pipeline = self.pipelines.get(pipeline_id)
        if pipeline is None:
            return None
        if self.access_checker.authorize(user, pipeline, "read"):
            return pipeline
        return None

    def trigger_build(self, user: User, pipeline_id: str,
                      params: Optional[Dict] = None) -> Dict:
        pipeline = self.pipelines.get(pipeline_id)
        if pipeline is None:
            return {"error": "Pipeline not found"}
        if not self.access_checker.authorize(user, pipeline, "execute"):
            return {"error": "Access denied"}
        return {"status": "triggered", "pipeline_id": pipeline_id}

    def _encrypt_secret(self, plaintext: str) -> str:
        """Encrypt a secret value with AES-GCM (authenticated encryption).

        Returns a hex string of nonce || ciphertext so the value can be
        securely stored at rest and decrypted for use at build time.
        """
        aesgcm = AESGCM(self._secret_key)
        nonce = os.urandom(12)
        ciphertext = aesgcm.encrypt(nonce, plaintext.encode(), None)
        return (nonce + ciphertext).hex()

    def _decrypt_secret(self, stored: str) -> str:
        """Decrypt a previously stored secret value."""
        data = bytes.fromhex(stored)
        nonce, ciphertext = data[:12], data[12:]
        aesgcm = AESGCM(self._secret_key)
        return aesgcm.decrypt(nonce, ciphertext, None).decode()

    def update_pipeline_secrets(self, user: User, pipeline_id: str,
                                secret_key: str, secret_value: str) -> Dict:
        pipeline = self.pipelines.get(pipeline_id)
        if pipeline is None:
            return {"error": "Pipeline not found"}
        if not self.access_checker.authorize(user, pipeline, "manage_secrets"):
            return {"error": "Access denied"}
        # Store secrets using authenticated encryption so they are protected
        # at rest but remain recoverable for build-time use.
        pipeline.secrets[secret_key] = self._encrypt_secret(secret_value)
        return {"status": "secret_updated", "key": secret_key}

    def list_pipelines_for_user(self, requesting_user: User,
                                target_user_id: str) -> List[Pipeline]:
        """List pipelines accessible to a target user, filtered by requester's access.

        Used by team leads to audit what pipelines their team members can see.
        Only returns pipelines that the requesting_user themselves can access.
        """
        results = []
        for pipeline in self.pipelines.values():
            # Authorize based on the requesting user's own permissions
            if self.access_checker.authorize(requesting_user, pipeline, "read"):
                results.append(pipeline)
        return results

    def clone_pipeline(self, user: User, source_pipeline_id: str,
                       new_name: str) -> Dict:
        """Clone a pipeline configuration. Requires read on source."""
        source = self.pipelines.get(source_pipeline_id)
        if source is None:
            return {"error": "Source pipeline not found"}
        if not self.access_checker.authorize(user, source, "read"):
            return {"error": "Access denied to source pipeline"}
        new_pipeline = self.create_pipeline(
            user, new_name, source.team_id, source.is_private
        )
        # Clone configuration but not secrets
        return {"status": "cloned", "new_pipeline_id": new_pipeline.pipeline_id}
